# -*- coding: utf-8 -*-
"""
租房问答对数据集 - 替换 jpkb 表中的法律知识问答对
用途：让 BM25(MySQL) 命中租房问题，便于对比 MySQL / Redis / RAG 三条检索链路响应时长
每个条目：学科名称=租房, 问题, 答案（依据《民法典》《住房租赁条例》等）
"""
RENTAL_QA = [
    # ========== 押金类 ==========
    ("租房", "房东不退押金怎么办？", "先协商，协商不成可申请调解、仲裁或起诉。依据《住房租赁条例》第三十五条，押金纠纷由出租人和承租人协商解决；协商不成的，可依法申请调解、仲裁或提起诉讼。同时第十条规定：房东收取押金，必须在合同中明确约定押金数额、返还时间及扣减情形；除合同约定且正当的情形外，房东不得擅自扣减押金。建议保留租赁合同、付款凭证、沟通记录，书面催告房东限期退还。"),
    ("租房", "租房押金一般交多少？", "法律对押金数额没有全国统一上限，实践中一般不超过两个月租金，常见为一个月租金，具体由双方协商并在合同中约定。依据《住房租赁条例》第十条，出租人收取押金的，应当在住房租赁合同中约定押金的数额、返还时间以及扣减押金的情形等事项。"),
    ("租房", "押金和定金有什么区别？", "押金是担保金，合同履行完毕后应如数退还，不具有惩罚性质；定金具有担保债务履行的性质，适用定金罚则（给付方违约无权要求返还，收受方违约应双倍返还）。租房实践中一般收取的是押金而非定金，交钱时务必看清收据写的是哪一种。"),
    ("租房", "退租时押金可以抵扣水电费吗？", "若租客确实欠缴水电费，房东可以凭缴费凭证从押金中扣除相应金额，但必须提供真实依据，不能随意扣减。依据《住房租赁条例》第十条，除合同约定且正当的情形外，出租人不得擅自扣减押金。建议退租前自行结清水电燃气费用并保留单据。"),
    ("租房", "租客违约房东能扣全部押金吗？", "不能随意扣全部。押金扣减应限于合同约定的违约金或实际损失范围。若违约金明显高于实际损失（一般超过损失的30%），租客可请求适当减少。依据《民法典》第五百八十五条，约定的违约金过分高于造成的损失的，人民法院或仲裁机构可以根据当事人的请求予以适当减少。"),
    ("租房", "提前退租押金能要回来吗？", "看合同约定和退租原因。若合同约定提前退租需支付违约金，房东可以从押金中抵扣违约金部分后返还剩余押金；若退租是因房屋存在安全隐患等房东原因，租客可依法解除合同并要求全额退还押金。建议提前与房东书面沟通，保留证据。"),
    # ========== 退租/解约类 ==========
    ("租房", "租客提前退租需要承担什么责任？", "依据合同约定承担违约责任，一般表现为支付违约金（如一个月租金）。依据《民法典》第五百六十二条、五百六十三条，双方可协商解除合同，出现法定情形（如房屋危及安全、房东违约致合同目的不能实现）租客可依法解除且不承担违约责任。违约金过高的可请求法院适当减少。"),
    ("租房", "退租要提前多久通知房东？", "按合同约定执行，一般合同会约定提前15天或30天书面通知；合同未约定的，应提前合理期限通知（司法实践通常认为15-30天较合理）。依据《民法典》第七百三十条，租赁期限届满，承租人继续使用租赁物且出租人没有提出异议的，原租赁合同继续有效，为不定期租赁。"),
    ("租房", "什么情况下租客可以无条件解除租赁合同？", "依据《民法典》第七百三十一条，租赁物危及承租人的安全或者健康的，即使承租人订立合同时明知该租赁物质量不合格，承租人仍然可以随时解除合同。此外，出租人未按约定提供房屋、房屋无法正常使用等致合同目的不能实现时，租客也可依法解除合同。"),
    ("租房", "房东不退租金怎么办？", "若房东无正当理由拒绝退还剩余租金，租客可先书面催告，协商不成可向人民调解委员会申请调解，或依据合同约定申请仲裁、向法院起诉。注意保留合同、付款凭证、退租交接记录等证据。"),
    ("租房", "不定期租赁合同怎么解除？", "依据《民法典》第七百三十条，不定期租赁合同的当事人可以随时解除合同，但是应当在合理期限之前通知对方。合理期限一般参考租金支付周期，按月付租的建议提前一个月通知。"),
    # ========== 合同类 ==========
    ("租房", "租房合同需要书面形式吗？", "依据《民法典》第七百零七条，租赁期限六个月以上的，应当采用书面形式。当事人未采用书面形式，无法确定租赁期限的，视为不定期租赁。为避免纠纷，建议无论租期长短都签订书面合同，明确租金、押金、维修、违约责任等条款。"),
    ("租房", "房东可以随意涨房租吗？", "合同期内不可以单方涨租。依据《民法典》第五百四十三条，变更合同应当经双方协商一致。房东单方涨价租客可拒绝履行；续租时租金可由双方协商确定，房东不得利用优势地位强制涨价。"),
    ("租房", "租房合同违约金多少合理？", "违约金由双方约定，司法实践中一般以不超过实际损失的30%为参考标准。依据《民法典》第五百八十五条，约定的违约金过分高于造成的损失的，当事人可以请求人民法院或者仲裁机构予以适当减少。常见约定为一个月租金。"),
    ("租房", "租客可以转租吗？", "依据《民法典》第七百一十六条，承租人经出租人同意，可以将租赁物转租给第三人。承租人未经出租人同意转租的，出租人可以解除合同。转租时建议取得房东书面同意，避免被认定为擅自转租。"),
    ("租房", "房东把房子卖了租客还能继续住吗？", "可以继续住。依据《民法典》第七百二十五条（买卖不破租赁），租赁物在承租人按照租赁合同占有期限内发生所有权变动的，不影响租赁合同的效力。新房东应继续履行原租赁合同至租期届满。"),
    ("租房", "租客有优先购买权吗？", "有。依据《民法典》第七百二十六条，出租人出卖租赁房屋的，应当在出卖之前的合理期限内通知承租人，承租人享有以同等条件优先购买的权利。但房屋按份共有人行使优先购买权或出租人将房屋出卖给近亲属的除外。"),
    ("租房", "租客的优先购买权怎么行使？", "出租人出卖租赁房屋前应在合理期限内通知承租人，承租人在收到通知后15日内未明确表示购买的，视为放弃优先购买权。依据《民法典》第七百二十六条，承租人仅在同等条件下享有优先购买权，若房东未履行通知义务，租客可主张优先购买权受到侵害的赔偿。"),
    # ========== 维修/费用类 ==========
    ("租房", "房屋维修费应该由谁承担？", "依据《民法典》第七百一十二条，出租人应当履行租赁物的维修义务，但当事人另有约定的除外。第七百一十三条：承租人在租赁物需要维修时可以请求出租人在合理期限内维修；出租人未履行维修义务的，承租人可以自行维修，维修费用由出租人负担。因维修租赁物影响承租人使用的，应当相应减少租金或者延长租期。"),
    ("租房", "物业费一般由谁交？", "以合同约定为准。合同未约定的，实践中物业费通常由出租人（业主）承担，因为物业服务合同是业主与物业公司签订的；部分城市习惯由承租人承担，建议签约时明确写入合同。"),
    ("租房", "房屋漏水找谁修？", "非承租人原因造成的漏水（如管道老化、防水层损坏）由出租人负责维修；因承租人使用不当造成的漏水由承租人承担维修费用。依据《民法典》第七百一十二条，出租人应履行维修义务，承租人应及时通知出租人维修。"),
    ("租房", "租房时供暖费谁交？", "看合同约定。北方集中供暖城市，若租金为「包暖」形式（含暖）则由房东承担；否则按面积分摊或由实际居住的租客承担，建议签约时明确。"),
    ("租房", "房子到期续租还要交中介费吗？", "一般不需要。续租是租客与房东直接延续租赁关系，通常不涉及中介服务，无需再支付中介费；若通过中介重新签订合同或中介提供了新的服务，则按约定执行。"),
    # ========== 合租/转租类 ==========
    ("租房", "合租和整租有什么区别？", "整租是指租客独立承租整套房屋，拥有完整的居住空间；合租是指多位租客共同承租一套房屋，各自拥有独立卧室，共享厨房、卫生间、客厅等公共区域。合租租金相对较低，但需与室友协调公共空间使用和费用分摊。"),
    ("租房", "群租房合法吗？", "不合法。依据《商品房屋租赁管理办法》第八条，出租住房应当以原设计的房间为最小出租单位，人均租住建筑面积不得低于当地人民政府规定的最低标准；厨房、卫生间、阳台和地下储藏室不得出租供人员居住。违规群租房可能面临行政处罚。"),
    ("租房", "二房东转租的房子能租吗？", "可以租，但务必确认二房东是否取得原房东同意。依据《民法典》第七百一十六条，承租人未经出租人同意转租的，出租人可以解除合同。签约前应查看二房东与原房东的租赁合同中的转租条款或书面同意证明。"),
    ("租房", "合租室友太吵影响休息怎么办？", "先与室友友好沟通；沟通无效可向房东或物业反映；若噪音达到扰民程度（如夜间超过规定分贝）可报警处理。同时建议在合租前明确作息、卫生、费用分摊等规则，写入合租协议。"),
    # ========== 权益保护类 ==========
    ("租房", "房东可以扣押租客身份证吗？", "不可以。扣押身份证属于违法行政强制行为，只有法定机关依法才能扣押。依据《民法典》相关规定及《居民身份证法》第十五条，任何组织或者个人不得扣押居民身份证。租客可拒绝并向公安机关举报。"),
    ("租房", "房东可以随意进出租客房间吗？", "不可以。租客取得房屋占有使用权后，房东未经同意不得随意进入。确需进入（如紧急维修、安全检查）应提前与租客协商并征得同意。擅自进入可能构成侵犯住宅权，租客可拒绝并要求赔偿。"),
    ("租房", "房子甲醛超标可以退租吗？", "可以。依据《民法典》第七百三十一条，租赁物危及承租人的安全或者健康的，即使承租人订立合同时明知该租赁物质量不合格，仍然可以随时解除合同。建议委托专业机构检测并保留检测报告作为证据。"),
    ("租房", "租客可以养宠物吗？", "以合同约定为准。合同明确禁止养宠物的应遵守；合同未约定的，在不影响他人居住、不损坏房屋的前提下通常可以饲养，但建议提前与房东沟通并写入合同，避免纠纷。"),
    ("租房", "退租时房屋有损坏谁负责？", "正常使用造成的自然磨损（如墙面轻微变色、家具自然老化）由房东承担；人为损坏（如墙面打孔破坏、家具恶意损坏）由租客承担赔偿责任。依据《民法典》第七百一十五条，承租人经出租人同意装饰装修的，合同解除时处理方式按约定或依法处理。"),
    ("租房", "房子被法院查封了还能继续住吗？", "租赁在先、查封在后且租客已实际占有的，租赁合同继续有效，租客可居住至租期届满；法院执行腾退时会依法保障承租人的合法权益。若房东隐瞒查封事实出租，租客可要求赔偿损失。"),
    ("租房", "租客能要求房东开发票吗？", "可以。出租人收取租金属于经营行为，应配合开具发票或租赁凭证，租客可要求房东提供租房发票用于报销或办理居住证。房东拒绝的，租客可向税务部门反映。"),
    ("租房", "租房时需要注意哪些事项？", "一、核实房屋产权（查看房产证与房东身份证一致）；二、签订书面合同并明确租金、押金、维修、违约等条款；三、签约前实地查看房屋状况并拍照留证；四、保留付款凭证与沟通记录；五、确认物业费、水电燃气费的承担方；六、警惕「低价」「先交定金再看房」等租房骗局。"),
    ("租房", "租客如何证明自己实际居住？", "保留租赁合同、租金转账记录、水电燃气缴费凭证、快递收货地址、居住证/暂住登记等均可作为实际居住证明。发生纠纷或办理居住证时可作为证据使用。"),
    ("租房", "租房合同丢了怎么办？", "可要求房东补签一份或出具书面确认；也可用租金转账记录、聊天记录、物业登记等证明租赁关系。依据《民法典》相关规定，租赁关系可通过实际履行行为佐证。"),
    ("租房", "因为工作调动必须提前退租能减免违约金吗？", "可以协商。工作调动属于个人原因，一般仍需按合同承担违约责任，但可与房东协商减免；若合同约定违约金过高（超过实际损失30%），依据《民法典》第五百八十五条可请求法院或仲裁机构适当减少。"),
    ("租房", "租房定金交了能退吗？", "依据定金罚则：若因租客原因不租了，定金一般不予退还；若因房东原因不租了，房东应双倍返还定金；若双方对合同内容未达成一致导致未能签约，定金应当返还。交定金前务必确认房源信息和签约意向。"),
    ("租房", "租客需要交中介费吗？", "一般需要，实践中通常由租客支付一个月租金作为中介费，部分城市或中介机构也接受房东承担或双方分摊。签约前应与中介明确中介费金额、支付时间及服务内容，并写入合同。"),
    ("租房", "租金一般多久一付？", "常见为押一付一（押金一个月+租金每月付）或押一付三（押金一个月+租金每季度付），具体由双方协商。依据《住房租赁条例》相关精神，鼓励按月支付，警惕要求一次性支付半年以上租金的高风险租赁（可能涉及「长收短付」骗局）。"),
]
